def palindromePartitions(s):
    n = len(s)
    pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            pal[i][j] = s[i] == s[j] and (j - i < 2 or pal[i + 1][j - 1])
    res = []
    cur = []

    def go(i):
        if i == n:
            res.append(cur[:])
            return
        for j in range(i, n):
            if pal[i][j]:
                cur.append(j - i + 1)
                go(j + 1)
                cur.pop()

    go(0)
    return res
